window.OL_I18N = {"lang":"vi","dict":{"meta.appName":"Kiểm tra tương thích eSIM Openline","meta.searchTitle":"{q} tương thích eSIM · Openline","ui.skip":"Chuyển đến nội dung","ui.brandAria":"Openline — Kiểm tra độ tương thích của thiết bị","ui.brandSub":"Kiểm tra độ tương thích của thiết bị","lang.label":"Ngôn ngữ","lang.aria":"Đổi ngôn ngữ","hero.titleHtml":"Thiết bị của bạn có hỗ trợ <span class=\"accent\">eSIM</span> không?","hero.tag":"Điện thoại, máy tính bảng, đồng hồ thông minh, bộ phát Wi-Fi — chỉ cần nhập thương hiệu hoặc model, chúng tôi sẽ cho bạn biết ngay liệu Openline có thể kích hoạt trên thiết bị đó hay không.","search.placeholder":"Thử “iPhone 18 Pro”, “Galaxy Z Fold8”, “Pixel Watch 5”, “iPad Air” hoặc mã model…","search.aria":"Tìm kiếm thương hiệu, tên model hoặc mã model của thiết bị","search.clear":"Xóa tìm kiếm","stats.devices":"thiết bị","stats.compatible":"tương thích","stats.notCompatible":"không tương thích","stats.brands":"thương hiệu","filters.label":"Bộ lọc","filters.summaryAll":"Tất cả thiết bị · Tất cả thương hiệu","filters.explain":"Chọn trạng thái tương thích và/hoặc một hay nhiều thương hiệu. Bộ lọc kết hợp với ô tìm kiếm và cập nhật danh sách bên dưới ngay lập tức.","filters.compat":"Độ tương thích","filters.compatAria":"Bộ lọc độ tương thích","filters.brands":"Thương hiệu","filters.brandsAria":"Bộ lọc thương hiệu","filters.clearAll":"Xóa tất cả","filters.compatOnly":"Chỉ thiết bị tương thích","filters.notCompatOnly":"Chỉ thiết bị không tương thích","filters.allStatuses":"Tất cả trạng thái","filters.nBrands":{"other":"{n} thương hiệu"},"filters.matchHtml":{"other":"<strong>{n}</strong> thiết bị phù hợp"},"cat.count":{"other":"{n} thiết bị"},"results.all":"Tất cả thiết bị","results.matching":"Thiết bị phù hợp","results.ofTotalHtml":"<strong>{n}</strong> trên {total}","results.totalHtml":"Tổng cộng <strong>{n}</strong>","results.showingFirst":" · hiển thị {max} kết quả đầu tiên","legend.ok":"Hỗ trợ eSIM","legend.err":"Chỉ dùng SIM vật lý","status.ok":"Tương thích","status.no":"Không tương thích","status.okAria":"Tương thích eSIM","status.noAria":"Không tương thích eSIM","note.caveatAria":"Lưu ý khu vực: {note}","popover.aria":"Lưu ý khu vực","popover.close":"Đóng","empty.noMatchTitle":"Không tìm thấy kết quả chính xác.","empty.noMatchBodyHtml":"Hãy thử chỉ nhập tên thương hiệu (vd: <em>Samsung</em>) hoặc mã model chính xác (vd: <em>SM-S921B</em>). Nếu thiết bị ra mắt sau năm 2021 và phát hành ngoài Trung Quốc đại lục, khả năng rất cao là có hỗ trợ eSIM.","empty.bothTitle":"Không có thiết bị nào khớp với cả tìm kiếm và bộ lọc.","empty.bothBodyHtml":{"other":"Tìm kiếm <em>{q}</em> có tổng cộng <strong>{n}</strong> thiết bị, nhưng không thiết bị nào khớp với bộ lọc hiện tại. Có thể bộ lọc đang gây xung đột?"},"empty.filtersTitle":"Không có thiết bị nào khớp với bộ lọc.","empty.filtersBody":"Hãy thử nới lỏng bộ lọc — việc kết hợp trạng thái tương thích hiếm gặp với ít thương hiệu có thể khiến không còn kết quả nào.","empty.nothing":"Chưa có gì ở đây.","empty.resetFilters":"Đặt lại bộ lọc","empty.clearSearch":"Xóa tìm kiếm","footer.privacy":"Quyền riêng tư","footer.terms":"Điều khoản","footer.socialAria":"Openline trên mạng xã hội","footer.onNetwork":"Openline trên {network}","footer.handleOnNetwork":"@askopenline trên {network}","footer.indexedHtml":"Đã lập chỉ mục <b id=\"footer-total\">{n}</b> thiết bị","region.US":"Hoa Kỳ","region.HK":"Hồng Kông","region.CN":"Trung Quốc đại lục","region.KR":"Hàn Quốc","region.JP":"Nhật Bản","region.AU":"Úc","region.TW":"Đài Loan","region.SEA":"Đông Nam Á","region.EU":"Liên minh châu Âu","region.IN":"Ấn Độ","region.UK":"Vương quốc Anh","exp.carrierWatch":"Đồng hồ thông minh có Cellular nhận eSIM thông qua gói cước đồng hồ của nhà mạng, được thiết lập từ ứng dụng đi kèm trên điện thoại đã ghép nối (ứng dụng Apple Watch, Galaxy Wearable, ứng dụng Pixel Watch). Mã QR eSIM của điện thoại hoặc eSIM du lịch không thể cài trực tiếp lên đồng hồ, vì vậy hãy kiểm tra xem nhà mạng của bạn có cung cấp gói cước cho mẫu đồng hồ này không.","exp.gpsOnly":"Đây là phiên bản chỉ có GPS. Thiết bị không có modem di động nên không thể dùng eSIM. Phiên bản GPS + Cellular của cùng mẫu đồng hồ có mã model khác.","exp.cnHkMoDualNano":"iPhone thế hệ này bán tại Trung Quốc đại lục, Hồng Kông và Ma Cao có hai khe nano-SIM vật lý và không có eSIM. Openline không thể cài đặt trên các máy này. Hãy kiểm tra mã model trong Cài đặt › Cài đặt chung › Giới thiệu.","exp.cnDualNano":"Phiên bản Trung Quốc đại lục của mẫu máy này dùng hai nano-SIM vật lý và không có eSIM. Các phiên bản bán ở nơi khác đều hỗ trợ eSIM. Hãy kiểm tra mã model trong Cài đặt › Cài đặt chung › Giới thiệu.","exp.cnLocalRules":"Phiên bản Trung Quốc đại lục có hỗ trợ eSIM, nhưng các nhà mạng Trung Quốc chỉ kích hoạt eSIM tại cửa hàng kèm xác minh giấy tờ tùy thân, và không thể cài hồ sơ eSIM nước ngoài khi đang ở Trung Quốc đại lục. Ngoài Trung Quốc, các eSIM du lịch như Openline vẫn cài đặt bình thường.","exp.esimOnlyUsJpCaGulf":"Máy bán tại Hoa Kỳ, Canada, Nhật Bản, Mexico và các nước vùng Vịnh không có khay SIM và chỉ hoạt động với eSIM. Ở nơi khác, máy có thêm khay nano-SIM, và bản Trung Quốc đại lục có thể không có eSIM. Openline hoạt động trên mọi phiên bản có hỗ trợ eSIM.","exp.noSimTray":"Phiên bản này không có khay SIM vật lý: mọi đường truyền, kể cả Openline, đều được thêm dưới dạng eSIM. Bạn có thể lưu nhiều eSIM và chuyển đổi giữa chúng trong Cài đặt.","exp.iden":"Thiết bị này chạy trên mạng iDEN của Motorola (đàm thoại bấm-để-nói Nextel / Boost), mạng đã bị Sprint ngừng hoạt động hoàn toàn vào tháng 6/2013. Thiết bị không thể kết nối với bất kỳ mạng di động hiện đại nào — dù có eSIM hay không. Chỉ còn giá trị sưu tầm/bảo tàng.","exp.cdmaVerizon":"Đây là thiết bị chỉ hỗ trợ CDMA, dành cho mạng CDMA 2G/3G cũ của Verizon, đã ngừng hoạt động vào ngày 31/12/2022. Máy hoàn toàn không có khe SIM (cả vật lý lẫn eSIM) — mạng CDMA xác thực qua ESN/MEID của máy chứ không qua SIM. Không thể dùng với Openline hay bất kỳ nhà mạng hiện đại nào.","exp.cdmaSprint":"Đây là thiết bị CDMA dành cho mạng cũ của Sprint, mạng đã bị T-Mobile ngừng hoạt động vĩnh viễn vào ngày 31/5/2022. Các mẫu Sprint đời sau có thêm LTE/GSM nhưng các đời đầu chỉ có CDMA và không thể kết nối với bất kỳ mạng hiện đại nào — dù có eSIM hay không.","exp.sunset":"Thiết bị này phụ thuộc vào mạng 3G hoặc 4G đời cũ đã bị các nhà mạng ngừng hoạt động (AT&T tắt 3G tháng 2/2022, T-Mobile tháng 2/2022, Verizon tháng 12/2022, đa số mạng 3G châu Âu trước năm 2025). Dù khe SIM vẫn hoạt động, ở hầu hết các quốc gia cũng không còn mạng để kết nối.","exp.windowsPhone":"Thiết bị này chạy Windows Phone (hoặc Windows 10 Mobile), hệ điều hành đã bị Microsoft ngừng phát triển từ năm 2019 — kho ứng dụng Store, các bản vá bảo mật và hầu hết dịch vụ gốc đều đã ngừng hoạt động. Máy không có phần cứng eSIM và gần như không còn ứng dụng hiện đại nào hỗ trợ. Không thể dùng làm máy chính hằng ngày.","exp.kaios":"Đây là điện thoại phổ thông chạy KaiOS. Hầu như không có thiết bị KaiOS nào hỗ trợ eSIM — chúng dùng SIM vật lý (thường là nano-SIM) và nhắm đến thị trường điện thoại phổ thông 4G giá rẻ như Ấn Độ (JioPhone) và châu Phi. Openline không thể cài đặt trên máy này.","exp.telematics":"Đây là mô-đun kết nối trên xe (Tesla, BMW, Audi, v.v.) với eSIM được hàn sẵn từ nhà máy lên bo mạch kết nối của xe. eSIM do hãng xe cấu hình tại nhà máy và không thể thay bằng hồ sơ do người dùng cài như Openline. Người dùng không thể tự bảo trì.","exp.satellite":"Đây là thiết bị liên lạc vệ tinh/GPS (Garmin inReach, SPOT, Zoleo, Iridium GO) dùng mạng vệ tinh Iridium hoặc Globalstar — không phải mạng di động GSM/LTE. Thiết bị không thể dùng eSIM theo nghĩa thông thường; kết nối gắn với gói thuê bao riêng của nhà sản xuất thiết bị định vị.","exp.medical":"Đây là thiết bị cảnh báo y tế hoặc ứng cứu khẩn cấp cá nhân (PERS). Modem di động của máy bị khóa theo nhà cung cấp dịch vụ (Lively, Medical Guardian, Life Alert, Bay Alarm) và chỉ hoạt động với gói giám sát của họ. Không thể cài eSIM của bên thứ ba.","exp.rugged":"Đây là thiết bị Samsung doanh nghiệp/siêu bền (dòng Galaxy XCover) dành cho nhân sự làm việc thực địa — kho bãi, y tế, khách sạn. Máy hỗ trợ eSIM nhưng việc kích hoạt có thể phải qua cấu hình Samsung Knox MDM của công ty bạn. Nếu máy đã mở khóa, Openline cài đặt như trên điện thoại thông thường.","exp.harmony":"Thiết bị này chạy HarmonyOS (Huawei) và không có Google Mobile Services. Việc kích hoạt eSIM thường cần ứng dụng dịch vụ nhà mạng của Huawei EMUI/HarmonyOS; hồ sơ Openline vẫn được cấp qua mã QR, nhưng cách kích hoạt qua Google Wallet thì không hoạt động. Máy bán tại Trung Quốc đại lục còn có thể từ chối hồ sơ eSIM quốc tế do hạn chế của firmware Trung Quốc.","exp.dualEsimOnly":"Phiên bản này hỗ trợ đồng thời hai eSIM nhưng không có khay SIM vật lý. Openline vẫn hoạt động — chỉ là bạn không thể dùng kèm nano-SIM. Trên một số phiên bản theo khu vực, mỗi lúc chỉ có thể bật một eSIM.","exp.euCarrier":"Một số phiên bản của thiết bị này khóa theo nhà mạng châu Âu được xuất xưởng với eSIM bị tắt ở cấp firmware. Các model mở khóa/quốc tế hỗ trợ eSIM bình thường. Hãy hỏi nhà mạng ban đầu nếu không kích hoạt được.","exp.usCarrier":"Đây là phiên bản mang thương hiệu nhà mạng Mỹ (AT&T, T-Mobile, Verizon, Sprint) với firmware bị khóa và thường chỉ hỗ trợ băng tần riêng của nhà mạng. eSIM có thể bị tắt hoặc chỉ dùng được hồ sơ của nhà mạng đó. Máy quốc tế đã mở khóa cùng model thường dùng được Openline; máy mang thương hiệu nhà mạng thì có thể không.","exp.verizon":"Các máy Pixel này bản mang thương hiệu Verizon bị tắt eSIM khi ra mắt trên mạng Verizon. Máy đã mở khóa và máy của nhà mạng khác ngoài Verizon hỗ trợ eSIM bình thường.","exp.googleFi":"Trên thế hệ Pixel này, eSIM chỉ khả dụng qua Google Fi tại Mỹ. Các nhà mạng khác chỉ dùng SIM vật lý. Máy quốc tế đã mở khóa hỗ trợ eSIM ở mọi nơi.","exp.usEsimOnly":"Trên iPhone thế hệ này mua tại Mỹ, Apple đã loại bỏ hoàn toàn khay SIM vật lý — bạn bắt buộc phải dùng eSIM. Ở nơi khác, máy có thêm khay SIM vật lý bên cạnh eSIM. Openline đều hoạt động ở cả hai trường hợp.","exp.cnOnly":"Thiết bị này xuất xưởng với firmware nội địa Trung Quốc. Trên giấy tờ có hỗ trợ eSIM nhưng hồ sơ quốc tế thường không kích hoạt được ngoài Trung Quốc đại lục. Nếu bạn định đi du lịch, hãy xác nhận việc kích hoạt eSIM với người bán trước khi mua.","exp.jpDomestic":"Điện thoại mang thương hiệu nhà mạng Nhật Bản (NTT DoCoMo, au, SoftBank, Rakuten) thường bị khóa băng tần theo quy hoạch tần số của Nhật. Phần cứng eSIM hoạt động tại Nhật; việc kích hoạt ở nước ngoài phụ thuộc vào mức trùng băng tần với mạng địa phương.","exp.regionLocked":"Việc kích hoạt eSIM của thiết bị này bị khóa theo vùng ở cấp firmware. Máy chỉ chấp nhận hồ sơ eSIM từ các nhà mạng tại quốc gia/khu vực nơi máy được bán.","exp.krOnly":"Model này chỉ bán tại Hàn Quốc và dùng băng tần của nhà mạng KT/SKT/LGU+. Máy có phần cứng eSIM nhưng việc kích hoạt ở nước ngoài không ổn định.","exp.foldable":"Đây là thiết bị màn hình gập — máy có khe eSIM nhưng lưu ý một số phiên bản gập bán tại Trung Quốc bị lược bỏ hỗ trợ eSIM quốc tế. Hãy kiểm tra mã model có khớp với phiên bản quốc tế (global SKU) không.","exp.hotspot":"Đây là bộ phát Wi-Fi di động / router MiFi chứ không phải điện thoại. Thiết bị nhận eSIM để chia sẻ dữ liệu di động cho các thiết bị khác của bạn. Openline được cấp theo cách giống như trên điện thoại.","exp.simTrayOnly":"Thiết bị này có modem di động nhưng chỉ nhận nano-SIM hoặc micro-SIM vật lý — không có chip eSIM. Bạn không thể cài Openline dưới dạng eSIM ở đây; bạn cần gói cước SIM vật lý.","exp.wifiOnly":"Phiên bản này chỉ có Wi-Fi — không có modem di động. Không thể cài bất kỳ eSIM nào. Hãy tìm phiên bản LTE / 5G / Cellular của cùng model.","exp.ereader":"Đây là máy đọc sách có modem di động tích hợp sẵn, gắn với gói dữ liệu miễn phí của nhà sản xuất (Amazon Whispernet, B&N nook, v.v.). eSIM/SIM không do người dùng cấu hình được — bạn không thể thay bằng hồ sơ Openline.","exp.cellularEsimOnly":"Phiên bản này chỉ có kết nối di động qua eSIM — máy không có khay SIM vật lý. Openline cài đặt trực tiếp qua mã QR.","exp.unverifiedVariant":"Dữ liệu của chúng tôi gắn mã model này với nhiều dòng sản phẩm. Thường là do Apple/Samsung/Google dùng lại mã nội bộ qua các thế hệ, hoặc một mã SKU khu vực đã được đổi tên. Openline vẫn nên hoạt động, nhưng nếu mã model trên hộp không khớp với thiết bị bạn đang xem, hãy kiểm tra lại với nhà sản xuất trước khi mua.","exp.crossBrand":"Mã model này cũng xuất hiện trên thiết bị của một thương hiệu khác (Vivo/iQOO, Xiaomi/POCO, Nokia/HMD, Nubia/ZTE, v.v.). Thường đó là các thương hiệu cùng công ty — phần cứng thường giống nhau, đôi khi chỉ đổi thương hiệu — nhưng hỗ trợ eSIM và chứng nhận nhà mạng có thể khác nhau giữa hai thương hiệu. Hãy đối chiếu với hộp bán lẻ thực tế của máy bạn.","exp.modelUnverified":"Chúng tôi chưa có mã model/mã linh kiện chính thức cho thiết bị này — thường vì đây là thiết bị đeo, mô-đun kết nối trên xe, bộ phát Wi-Fi hoặc phụ kiện không công bố công khai mã SKU. Hỗ trợ eSIM có trong bảng thông số của nhà sản xuất, nhưng Openline không thể đối chiếu mã phần cứng cụ thể để đảm bảo tương thích. Hãy xác nhận với nhà sản xuất trước khi quyết định.","exp.ambiguous":"Tên sản phẩm ở đây rất ngắn (“13”, “F7”, “M6”…) và dễ nhầm với các model cùng số của thương hiệu hoặc thế hệ khác. Hãy kiểm tra thương hiệu và mã model trên thiết bị để chắc chắn mục này đúng với máy bạn đang dùng.","exp.cnFirmware":"Thiết bị này xuất xưởng với firmware nội địa Trung Quốc. Máy có phần cứng eSIM nhưng firmware Trung Quốc thường chặn kích hoạt hồ sơ eSIM quốc tế. Nếu bạn định dùng Openline ngoài Trung Quốc đại lục, hãy xác nhận với người bán rằng firmware không bị khóa vùng trước khi mua.","exp.regionExcluded":"Máy bán tại các khu vực sau không có phần cứng eSIM nên chỉ dùng được khay SIM vật lý: {regions}. Ở nơi khác, eSIM được hỗ trợ và Openline sẽ kích hoạt bình thường. Nếu bạn mua máy ở nước ngoài hoặc qua đơn vị nhập khẩu song song (hàng xách tay), hãy đối chiếu mã model với danh sách của nhà sản xuất.","note.3G free":"Không có 3G","note.3G/4G":"3G/4G","note.AU/JP/TW excluded":"Trừ AU/JP/TW","note.Ambiguous name":"Tên dễ nhầm","note.CDMA":"CDMA","note.CN firmware":"Firmware CN","note.CN/HK excluded":"Trừ CN/HK","note.CN/HK/MO: dual nano-SIM":"CN/HK/MO: 2 nano-SIM","note.CN/IN":"CN/IN","note.CN/IN dual-eSIM only":"CN/IN: chỉ dual-eSIM","note.CN: dual nano-SIM":"CN: 2 nano-SIM","note.CN: local eSIM rules":"CN: quy định eSIM riêng","note.Carrier watch plan":"Gói đồng hồ nhà mạng","note.Cross-brand model code":"Mã trùng hãng khác","note.E-reader":"Máy đọc sách","note.Enterprise rugged":"Máy doanh nghiệp siêu bền","note.Foldable":"Màn hình gập","note.GPS only":"Chỉ có GPS","note.GPS/satellite tracker":"Định vị GPS/vệ tinh","note.Google Fi/US only":"Chỉ Google Fi/US","note.HarmonyOS":"HarmonyOS","note.JP domestic band lock":"JP: khóa băng tần","note.KR only":"Chỉ KR","note.KR/CN":"KR/CN","note.KaiOS feature phone":"Điện thoại KaiOS","note.Medical alert":"Cảnh báo y tế","note.Mobile hotspot":"Bộ phát Wi-Fi","note.Model code unverified":"Mã model chưa xác minh","note.Nextel/Boost":"Nextel/Boost","note.No eSIM hardware":"Không có phần cứng eSIM","note.No eSIM in most regions":"Đa số vùng không có eSIM","note.Not on Verizon/Sprint":"Không dùng Verizon/Sprint","note.SEA excluded":"Trừ SEA","note.SIM tray only":"Chỉ có khay SIM","note.Sprint":"Sprint","note.US carrier variant":"Bản nhà mạng US","note.US model excluded":"Trừ bản US","note.US variant excluded":"Trừ bản US","note.US/HK excluded":"Trừ US/HK","note.US/JP: eSIM ok":"US/JP: dùng được eSIM","note.US: eSIM only":"US: chỉ có eSIM","note.Unverified variant":"Biến thể chưa xác minh","note.Vehicle telematics":"Kết nối trên xe","note.Verizon":"Verizon","note.Verizon US no eSIM":"Verizon US không có eSIM","note.Verizon-only 5G":"Chỉ 5G Verizon","note.Wi-Fi + Cellular only":"Chỉ Wi-Fi + Cellular","note.Wi-Fi + free 4G":"Wi-Fi + 4G miễn phí","note.Wi-Fi only":"Chỉ có Wi-Fi","note.Wi-Fi only in most regions":"Đa số vùng chỉ có Wi-Fi","note.Wi-Fi/3G":"Wi-Fi/3G","note.Windows Phone":"Windows Phone","note.deprecated":"ngừng hỗ trợ","note.dual-eSIM in EU":"dual-eSIM tại EU","note.eSIM only":"Chỉ có eSIM","note.eSIM only (no SIM tray)":"Chỉ eSIM (không khay SIM)","note.eSIM only in US/JP/CA/Gulf":"Chỉ eSIM tại US/JP/CA/Vùng Vịnh","note.eSIM only via Google Fi":"Chỉ eSIM qua Google Fi","note.iDEN":"iDEN","note.sunset":"đã tắt sóng"}};
